class Stock {
    int count_;
public:
    explicit Stock(int count) : count_(count) {
        if (count < 0 || count > 100) throw std::invalid_argument("range");
    }
    int count() const { return count_; }
    bool take(int amount) {
        if (amount < 0 || amount > count_) return false;
        count_ -= amount; // Private state changes only after validation.
        return true;
    }
};

int main() {
    Stock s(5);
    bool ok=s.take(5);
    std::cout<<std::boolalpha<<ok<<" "<<s.count()<<"\n";
    }

#include <iostream>
class Account{
    double balance_{};
public:
    bool withdraw(double amount){ if(amount < 0 || amount > balance_) return false; balance_ -= amount; return true; }
    void deposit(double amount){ if(amount > 0) balance_ += amount; }
    double balance() const { return balance_; }
};
int main(){ Account a; a.deposit(50); std::cout << a.withdraw(70) << ' ' << a.balance() << '\n'; }

#include <iostream>
class Thermostat{
    double target_{21.0};
public:
    explicit Thermostat(double t):target_(t){}
    bool should_heat(double current) const { return current < target_; }
};
int main(){ Thermostat t{22}; std::cout << std::boolalpha << t.should_heat(20.5) << '\n'; }

#include <iostream>

class Quantity {
public:
    static constexpr int maximum{1000};
    bool set(int candidate) {
        if (candidate < 0 || candidate > maximum) return false;
        value_ = candidate;
        return true;
    }
    int value() const { return value_; }
private:
    int value_{};
};

int main() {
    Quantity quantity;
    if (quantity.value() != 0) return 1;
    if (!quantity.set(12) || quantity.value() != 12) return 2;
    if (quantity.set(-1) || quantity.value() != 12) return 3;
    if (quantity.set(1001) || quantity.value() != 12) return 4;
    const Quantity& observed = quantity;
    std::cout << "quantity=" << observed.value() << '\n';
    std::cout << "PASS\n";
}

